-- V148: Офисная Академия — HR-трек (12 уроков)
-- Залы Асгарда: Кадровое дело

-- ═══════════════════════════════════════════════════════════════
-- УРОК 1: Подбор персонала
-- ═══════════════════════════════════════════════════════════════
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (2, 'hr', 'Подбор персонала — воронка, собеседования, оценка кандидатов', 'Кадровое дело', '👥', '#1e3830',
$blocks$[
  {"type":"cover","icon":"👥","title":"Подбор персонала","subtitle":"Как находить, оценивать и нанимать лучших"},
  {"type":"intro","text":"Подбор персонала в строительной компании — это не просто «разместить вакансию и ждать». Асгард работает на опасных промышленных объектах, и ошибка в найме может стоить здоровья людей и репутации компании. Каждый кандидат проходит многоступенчатую проверку: от квалификации и допусков до психологической устойчивости для работы на вахте. В этом свитке — полный алгоритм подбора от заявки до выхода на работу."},
  {"type":"text_block","title":"Воронка подбора в Асгарде","text":"Воронка подбора — это последовательность этапов, через которые проходит каждый кандидат. В Асгарде воронка состоит из 6 этапов: 1) Заявка от руководителя — описание позиции, требования, сроки. 2) Поиск и привлечение — размещение вакансий, работа с базой, рекомендации. 3) Первичный скрининг — проверка резюме, телефонное интервью 10-15 минут. 4) Собеседование — очное или видео, 30-45 минут с HR + руководитель. 5) Проверка документов — допуски, медосмотр, судимость, рекомендации. 6) Оформление — трудовой договор, инструктажи, выдача СИЗ. Средняя конверсия воронки: из 100 откликов → 20 скринингов → 8 собеседований → 3 оффера → 2 выхода на работу."},
  {"type":"icon_grid","title":"6 этапов воронки подбора","items":[{"icon":"📋","label":"Заявка","desc":"Руководитель описывает позицию, требования и сроки закрытия"},{"icon":"🔍","label":"Поиск","desc":"Вакансии на HH, Avito, база кандидатов, рекомендации сотрудников"},{"icon":"📞","label":"Скрининг","desc":"Телефонное интервью 10-15 мин: опыт, ожидания, готовность к вахте"},{"icon":"🤝","label":"Собеседование","desc":"Очное/видео 30-45 мин с HR и руководителем подразделения"},{"icon":"📄","label":"Проверка","desc":"Допуски, медосмотр, справка о судимости, рекомендации"},{"icon":"✅","label":"Оформление","desc":"Договор, инструктажи, СИЗ, знакомство с командой"}]},
  {"type":"warning","level":"danger","text":"Никогда не отправляйте на объект сотрудника без действующего медосмотра и обязательных допусков. Штраф за допуск к работе без медосмотра — до 130 000 рублей на компанию (ст. 5.27.1 КоАП). При несчастном случае — уголовная ответственность."},
  {"type":"text_block","title":"Особенности подбора для вахтовой работы","text":"Вахтовая работа предъявляет особые требования к кандидатам. Помимо профессиональных навыков, HR должен оценить: готовность к длительным командировкам (28/28 или 45/45), психологическую устойчивость (работа в замкнутом коллективе, удалённость от семьи), отсутствие вредных привычек (на НПЗ строгий сухой закон), физическое здоровье (работа на высоте, с химикатами, при экстремальных температурах). Статистика Асгарда: 35% новичков увольняются в первые 3 месяца. Главная причина — неготовность к вахтовому режиму. Поэтому на собеседовании обязательно задавайте вопрос: «Расскажите о вашем опыте вахтовой работы и как вы справлялись с трудностями»."},
  {"type":"steps","title":"Алгоритм телефонного скрининга (10 минут)","items":["Представиться: имя, компания Асгард, направление деятельности (1 мин)","Уточнить актуальность поиска работы и готовность к вахте (1 мин)","Проверить ключевые квалификации: разряд, допуски, НАКС, стаж (2 мин)","Спросить об опыте на аналогичных объектах: НПЗ, химия, нефтедобыча (2 мин)","Обсудить зарплатные ожидания и условия: ставка, суточные, проживание (2 мин)","Уточнить сроки готовности к выезду и наличие загранпаспорта (1 мин)","Договориться о следующем шаге: собеседование или отказ с обратной связью (1 мин)"]},
  {"type":"scenario","title":"Кандидат идеален по навыкам, но нет опыта вахты","text":"К вам пришёл сварщик НАКС с 10-летним стажем, отличными рекомендациями, всеми допусками. Но он никогда не работал вахтовым методом — всегда работал в городе. Руководитель говорит: «Берём, он нам очень нужен». Как поступить?","resolution":"Не отказывать, но и не скрывать реальность. 1) Провести подробную беседу о вахтовом режиме: 28 дней без семьи, общежитие/вагончик, сухой закон, строгий распорядок. 2) Предложить первую вахту укороченную — 14 дней вместо 28, чтобы адаптироваться. 3) Назначить наставника из опытных вахтовиков. 4) Через 2 недели — обратная связь: готов ли продолжать. Это снижает риск увольнения с 35% до 15%."},
  {"type":"stat","value":"35%","label":"новичков увольняются в первые 3 месяца из-за неготовности к вахте","source":"HR-аналитика Асгарда 2025"},
  {"type":"fact_card","icon":"💡","text":"Программа «Приведи друга» в Асгарде даёт бонус 15 000 рублей сотруднику, чей рекомендованный кандидат проработал 3 месяца. За 2025 год через рекомендации пришли 28% новых сотрудников — и их текучесть в 2 раза ниже, чем у найденных через HH.ru."},
  {"type":"highlight","text":"Конверсия воронки Асгарда: 100 откликов → 20 скринингов → 8 собеседований → 3 оффера → 2 выхода. Если ваша конверсия ниже — ищите узкое место."},
  {"type":"quote","text":"Нанимайте за характер, обучайте навыкам","author":"Питер Шульц, CEO Porsche"},
  {"type":"checklist","title":"Чек-лист перед оффером кандидату","items":["Профессиональные навыки подтверждены (разряд, допуски, НАКС)","Опыт вахтовой работы обсуждён, ожидания выровнены","Медосмотр пройден или назначена дата","Справка об отсутствии судимости запрошена","Рекомендации проверены (минимум 2)","Зарплатные ожидания в рамках бюджета","Руководитель подразделения одобрил кандидата"]},
  {"type":"divider"}
]$blocks$::jsonb, 10, ARRAY['подбор','воронка','собеседование','вахта','найм'], true, 'published', 'manual', NOW(), CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Сколько этапов в воронке подбора Асгарда?','[{"text":"4","is_correct":false},{"text":"5","is_correct":false},{"text":"6","is_correct":true},{"text":"8","is_correct":false}]','Воронка подбора состоит из 6 этапов: заявка, поиск, скрининг, собеседование, проверка, оформление.'),
(lid,2,'choice','Какой процент новичков увольняется в первые 3 месяца?','[{"text":"15%","is_correct":false},{"text":"25%","is_correct":false},{"text":"35%","is_correct":true},{"text":"50%","is_correct":false}]','35% новичков увольняются в первые 3 месяца, главная причина — неготовность к вахтовому режиму.'),
(lid,3,'choice','Каков штраф за допуск к работе без медосмотра?','[{"text":"30 000 ₽","is_correct":false},{"text":"80 000 ₽","is_correct":false},{"text":"130 000 ₽","is_correct":true},{"text":"500 000 ₽","is_correct":false}]','Штраф за допуск к работе без медосмотра — до 130 000 рублей на компанию (ст. 5.27.1 КоАП).'),
(lid,4,'choice','Какой бонус даёт программа «Приведи друга»?','[{"text":"5 000 ₽","is_correct":false},{"text":"10 000 ₽","is_correct":false},{"text":"15 000 ₽","is_correct":true},{"text":"25 000 ₽","is_correct":false}]','Бонус 15 000 рублей сотруднику, чей рекомендованный кандидат проработал 3 месяца.'),
(lid,5,'truefalse','Кандидата без опыта вахтовой работы нужно сразу отклонять.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','Не отказывать, а предложить укороченную первую вахту (14 дней) с наставником. Это снижает риск увольнения с 35% до 15%.'),
(lid,6,'choice','Какой процент новых сотрудников пришёл через рекомендации в 2025 году?','[{"text":"12%","is_correct":false},{"text":"28%","is_correct":true},{"text":"45%","is_correct":false},{"text":"60%","is_correct":false}]','Через рекомендации пришли 28% новых сотрудников, и их текучесть в 2 раза ниже.'),
(lid,7,'choice','Сколько длится телефонный скрининг?','[{"text":"5 минут","is_correct":false},{"text":"10-15 минут","is_correct":true},{"text":"30 минут","is_correct":false},{"text":"1 час","is_correct":false}]','Телефонный скрининг длится 10-15 минут — достаточно для первичной оценки.'),
(lid,8,'scenario','Руководитель просит срочно взять кандидата без проверки допусков. Что делать?','[{"text":"Взять — руководитель отвечает","is_correct":false},{"text":"Отказать и проверить допуски по стандартной процедуре","is_correct":true},{"text":"Взять на испытательный срок","is_correct":false},{"text":"Позвонить директору","is_correct":false}]','Никогда не пропускайте проверку допусков. Штраф до 130 000 ₽, при НС — уголовная ответственность.');
END $$;

-- ═══════════════════════════════════════════════════════════════
-- УРОК 2: Кадровый учёт — ТК РФ
-- ═══════════════════════════════════════════════════════════════
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (3, 'hr', 'Кадровый учёт — ТК РФ, договоры, приказы', 'Кадровое дело', '📋', '#1e3828',
$blocks$[
  {"type":"cover","icon":"📋","title":"Кадровый учёт","subtitle":"ТК РФ, трудовые договоры и обязательные документы"},
  {"type":"intro","text":"Кадровый учёт — фундамент HR-работы. Ошибка в трудовом договоре, пропущенный приказ или неправильно оформленное увольнение — это штрафы от ГИТ, суды с работниками и репутационные потери. В Асгарде кадровый учёт ведётся в CRM с автоматическими шаблонами, но HR обязан знать законодательство и контролировать каждый документ."},
  {"type":"text_block","title":"Трудовой договор: обязательные условия","text":"Трудовой договор — главный документ отношений работника и работодателя. По ст. 57 ТК РФ обязательные условия: место работы, трудовая функция, дата начала, условия оплаты, режим работы и отдыха, условия труда на рабочем месте, обязательное социальное страхование. Для вахтовых работников дополнительно: вахтовый метод работы (ст. 297 ТК), продолжительность вахты (не более 1 месяца, в исключительных случаях — до 3 месяцев), порядок предоставления межвахтового отдыха, размер надбавки за вахтовый метод. Типичная ошибка: не указать в договоре вахтовый метод — тогда работник может потребовать оплату как за обычный режим работы."},
  {"type":"icon_grid","title":"Обязательные кадровые документы","items":[{"icon":"📄","label":"Трудовой договор","desc":"Подписывается в 2 экземплярах в первый рабочий день"},{"icon":"📋","label":"Приказ о приёме","desc":"Форма Т-1, в течение 3 дней с даты начала работы"},{"icon":"📖","label":"Трудовая книжка","desc":"Запись о приёме в течение 5 рабочих дней (или ЭТК)"},{"icon":"🗂️","label":"Личная карточка Т-2","desc":"Заполняется при приёме, обновляется при изменениях"},{"icon":"📝","label":"Должностная инструкция","desc":"Подписывается работником при приёме"},{"icon":"🔒","label":"Согласие на ПДн","desc":"Обработка персональных данных — обязательно с 2006 года"}]},
  {"type":"warning","level":"danger","text":"Штрафы ГИТ за нарушения кадрового учёта: отсутствие трудового договора — до 100 000 ₽ за каждого работника; подмена трудового договора ГПХ — до 100 000 ₽; нарушение порядка увольнения — до 50 000 ₽ + восстановление работника с оплатой вынужденного прогула. При повторном нарушении штрафы удваиваются."},
  {"type":"text_block","title":"Увольнение: как не попасть в суд","text":"Увольнение — самый рискованный кадровый процесс. 80% трудовых споров в судах связаны с увольнениями. Правила Асгарда: 1) По собственному желанию (ст. 80 ТК) — заявление за 14 дней, приказ, расчёт и трудовая в последний день. 2) По соглашению сторон (ст. 78 ТК) — самый безопасный способ, оформляется письменное соглашение с указанием компенсации. 3) По инициативе работодателя (ст. 81 ТК) — только при наличии оснований и соблюдении процедуры. Каждое дисциплинарное взыскание оформляется: объяснительная → акт → приказ. Без документов суд восстановит работника."},
  {"type":"steps","title":"Алгоритм оформления приёма на работу","items":["Получить от кандидата: паспорт, СНИЛС, ИНН, трудовую книжку, военный билет, диплом","Оформить трудовой договор в 2 экземплярах — один работнику под подпись","Издать приказ о приёме (Т-1) в течение 3 дней","Внести запись в трудовую книжку в течение 5 рабочих дней","Заполнить личную карточку Т-2","Провести вводный инструктаж по охране труда (до начала работы!)","Ознакомить с ЛНА: ПВТР, положение об оплате, должностная инструкция","Оформить согласие на обработку персональных данных","Внести данные в CRM Асгарда"]},
  {"type":"stat","value":"100 000 ₽","label":"штраф за отсутствие трудового договора — за КАЖДОГО работника","source":"ст. 5.27 КоАП РФ"},
  {"type":"fact_card","icon":"⚖️","text":"В 2024 году суды восстановили на работе 67% уволенных по инициативе работодателя, когда процедура была нарушена. Средняя компенсация за вынужденный прогул — 180 000 рублей. Правильное документирование — единственная защита."},
  {"type":"scenario","title":"Работник не вышел на вахту без предупреждения","text":"Аппаратчик Иванов должен был выехать на вахту в понедельник. Не приехал, не позвонил, не отвечает на звонки. Прошло 3 дня. Мастер требует замену, РП злится. Можно ли уволить за прогул?","resolution":"Нельзя уволить сразу. Алгоритм: 1) Составить акт об отсутствии на рабочем месте за каждый день (подписи 2+ свидетелей). 2) Направить заказное письмо с уведомлением: «Просим объяснить причину отсутствия в течение 2 рабочих дней». 3) Дождаться ответа или составить акт об отказе от объяснений. 4) Только после этого — приказ об увольнении за прогул (пп. «а» п. 6 ст. 81 ТК). Без этой процедуры суд восстановит работника."},
  {"type":"highlight","text":"80% трудовых споров в судах — из-за увольнений. Каждое дисциплинарное взыскание: объяснительная → акт → приказ. Без документов суд на стороне работника."},
  {"type":"quote","text":"Закон суров, но это закон","author":"Латинская пословица"},
  {"type":"checklist","title":"Чек-лист кадрового аудита (ежемесячно)","items":["Все трудовые договоры подписаны в 2 экземплярах","Приказы о приёме изданы в срок (3 дня)","Трудовые книжки заполнены (5 дней)","Личные карточки Т-2 актуальны","Согласия на ПДн подписаны","Инструктажи по ОТ проведены до начала работы","Все изменения (перевод, отпуск) оформлены приказами"]},
  {"type":"divider"}
]$blocks$::jsonb, 11, ARRAY['кадры','ТК РФ','договор','увольнение','ГИТ'], true, 'published', 'manual', NOW(), CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','В какой срок нужно издать приказ о приёме на работу?','[{"text":"В день приёма","is_correct":false},{"text":"В течение 3 дней","is_correct":true},{"text":"В течение 5 дней","is_correct":false},{"text":"В течение 2 недель","is_correct":false}]','Приказ о приёме (Т-1) издаётся в течение 3 дней с даты начала работы.'),
(lid,2,'choice','Каков штраф за отсутствие трудового договора?','[{"text":"30 000 ₽","is_correct":false},{"text":"50 000 ₽","is_correct":false},{"text":"100 000 ₽","is_correct":true},{"text":"200 000 ₽","is_correct":false}]','Штраф до 100 000 ₽ за каждого работника без трудового договора.'),
(lid,3,'choice','Какой процент уволенных восстанавливается судом при нарушении процедуры?','[{"text":"30%","is_correct":false},{"text":"50%","is_correct":false},{"text":"67%","is_correct":true},{"text":"85%","is_correct":false}]','В 2024 году суды восстановили 67% уволенных при нарушении процедуры.'),
(lid,4,'truefalse','Работника можно уволить за прогул в тот же день, когда он не вышел.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','Нельзя. Нужно: акт об отсутствии → запрос объяснений (2 дня на ответ) → акт об отказе → только потом приказ.'),
(lid,5,'choice','Какова максимальная продолжительность вахты по ТК РФ?','[{"text":"1 месяц (до 3 в исключительных случаях)","is_correct":true},{"text":"2 месяца","is_correct":false},{"text":"45 дней","is_correct":false},{"text":"Без ограничений","is_correct":false}]','По ст. 299 ТК РФ вахта не более 1 месяца, в исключительных случаях — до 3 месяцев.'),
(lid,6,'choice','Средняя компенсация за вынужденный прогул при незаконном увольнении?','[{"text":"50 000 ₽","is_correct":false},{"text":"100 000 ₽","is_correct":false},{"text":"180 000 ₽","is_correct":true},{"text":"300 000 ₽","is_correct":false}]','Средняя компенсация за вынужденный прогул — 180 000 рублей.'),
(lid,7,'choice','В какой срок нужно внести запись в трудовую книжку?','[{"text":"В день приёма","is_correct":false},{"text":"В течение 3 дней","is_correct":false},{"text":"В течение 5 рабочих дней","is_correct":true},{"text":"В течение месяца","is_correct":false}]','Запись в трудовую книжку вносится в течение 5 рабочих дней.'),
(lid,8,'scenario','Работник не вышел на вахту 3 дня без объяснений. Первый шаг HR?','[{"text":"Издать приказ об увольнении","is_correct":false},{"text":"Составить акт об отсутствии и направить запрос объяснений","is_correct":true},{"text":"Позвонить родственникам","is_correct":false},{"text":"Подождать ещё неделю","is_correct":false}]','Первый шаг: акт об отсутствии за каждый день + заказное письмо с запросом объяснений (2 рабочих дня на ответ).');
END $$;

-- ═══════════════════════════════════════════════════════════════
-- УРОК 3: Адаптация новичков
-- ═══════════════════════════════════════════════════════════════
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (4, 'hr', 'Адаптация новичков — онбординг, наставничество, чек-листы', 'Кадровое дело', '🎓', '#1e3020',
$blocks$[
  {"type":"cover","icon":"🎓","title":"Адаптация новичков","subtitle":"Как превратить новичка в эффективного сотрудника за 90 дней"},
  {"type":"intro","text":"Первые 90 дней определяют, останется ли сотрудник в компании. Без системной адаптации 35% новичков уходят в первый квартал — и каждый уход стоит компании 2-3 месячных зарплаты (подбор, обучение, простой). В Асгарде действует программа адаптации «Путь воина» — структурированный онбординг с наставником, чек-листами и контрольными точками."},
  {"type":"text_block","title":"Программа «Путь воина» — 3 фазы","text":"Фаза 1 (дни 1-7): Знакомство. Новичок получает наставника, проходит вводные инструктажи, знакомится с CRM, получает доступы и оборудование. Ключевая задача — чтобы человек не чувствовал себя потерянным. Фаза 2 (дни 8-30): Погружение. Работа под наблюдением наставника, первые самостоятельные задачи, обратная связь каждую пятницу. Для вахтовых — первый выезд на объект с опытной бригадой. Фаза 3 (дни 31-90): Самостоятельность. Полноценная работа с минимальным контролем, оценка результатов, решение о прохождении испытательного срока. HR проводит exit-интервью на 30-й и 90-й день."},
  {"type":"icon_grid","title":"Что получает новичок в первый день","items":[{"icon":"👤","label":"Наставник","desc":"Опытный сотрудник, который отвечает на все вопросы первые 30 дней"},{"icon":"📱","label":"Доступ к CRM","desc":"Логин, пароль, обучение основным модулям — 1 час"},{"icon":"📋","label":"Чек-лист адаптации","desc":"Список задач на 90 дней с контрольными точками"},{"icon":"👕","label":"СИЗ и экипировка","desc":"Полный комплект защитной одежды и обуви по размеру"},{"icon":"📖","label":"Академия Асгарда","desc":"Обязательные уроки по роли — начать в первую неделю"},{"icon":"🤝","label":"Знакомство с командой","desc":"Представление коллегам, обед с руководителем"}]},
  {"type":"warning","level":"warning","text":"Наставник — не формальность. Это человек, который реально помогает новичку первые 30 дней. Наставник получает доплату 5 000 ₽/мес и освобождается от 10% текущей нагрузки. Без мотивированного наставника программа адаптации не работает."},
  {"type":"steps","title":"Чек-лист HR на первый день новичка","items":["Подготовить рабочее место: стол, компьютер, телефон, канцелярия","Создать учётную запись в CRM и email","Назначить наставника и уведомить его заранее","Провести вводный инструктаж по ОТ (до начала работы!)","Выдать СИЗ по размеру и под подпись","Представить коллегам и руководителю","Выдать чек-лист адаптации «Путь воина»","Назначить обед с руководителем в первый день"]},
  {"type":"stat","value":"2-3 зарплаты","label":"стоимость потери новичка в первые 90 дней (подбор + обучение + простой)","source":"HR-аналитика"},
  {"type":"fact_card","icon":"📊","text":"После внедрения программы «Путь воина» в 2024 году текучесть новичков в первые 90 дней снизилась с 35% до 18%. Экономия для компании — около 2,4 млн рублей в год (12 сохранённых сотрудников × 200 000 ₽ стоимость замены)."},
  {"type":"scenario","title":"Наставник не хочет заниматься новичком","text":"Вы назначили опытного мастера Петрова наставником для новичка. Через неделю новичок жалуется, что Петров его игнорирует: «Разбирайся сам, мне некогда». Петров говорит: «У меня своей работы хватает, я не нянька».","resolution":"1) Поговорить с Петровым: напомнить о доплате 5 000 ₽ и снижении нагрузки на 10%. 2) Уточнить, действительно ли нагрузка снижена — возможно, руководитель не выполнил свою часть. 3) Если Петров принципиально отказывается — заменить наставника. Не все подходят для этой роли. 4) Провести обратную связь с новичком: что конкретно нужно, какие вопросы. 5) Зафиксировать в CRM для учёта при выборе наставников в будущем."},
  {"type":"highlight","text":"Текучесть новичков снизилась с 35% до 18% после внедрения «Пути воина». Экономия — 2,4 млн ₽/год."},
  {"type":"quote","text":"Первое впечатление нельзя произвести дважды","author":"Коко Шанель"},
  {"type":"divider"}
]$blocks$::jsonb, 9, ARRAY['адаптация','онбординг','наставник','новичок','испытательный'], true, 'published', 'manual', NOW(), CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Сколько фаз в программе адаптации «Путь воина»?','[{"text":"2","is_correct":false},{"text":"3","is_correct":true},{"text":"4","is_correct":false},{"text":"5","is_correct":false}]','Программа «Путь воина» состоит из 3 фаз: Знакомство (1-7 дней), Погружение (8-30), Самостоятельность (31-90).'),
(lid,2,'choice','Какова доплата наставнику?','[{"text":"3 000 ₽/мес","is_correct":false},{"text":"5 000 ₽/мес","is_correct":true},{"text":"10 000 ₽/мес","is_correct":false},{"text":"15 000 ₽/мес","is_correct":false}]','Наставник получает доплату 5 000 ₽/мес и освобождается от 10% текущей нагрузки.'),
(lid,3,'choice','На сколько снизилась текучесть новичков после внедрения «Пути воина»?','[{"text":"С 35% до 25%","is_correct":false},{"text":"С 35% до 18%","is_correct":true},{"text":"С 50% до 30%","is_correct":false},{"text":"С 40% до 20%","is_correct":false}]','Текучесть снизилась с 35% до 18%, экономия — 2,4 млн ₽/год.'),
(lid,4,'choice','Сколько стоит потеря новичка в первые 90 дней?','[{"text":"1 зарплата","is_correct":false},{"text":"2-3 зарплаты","is_correct":true},{"text":"5 зарплат","is_correct":false},{"text":"Ничего не стоит","is_correct":false}]','Потеря новичка стоит 2-3 месячных зарплаты: подбор, обучение, простой.'),
(lid,5,'truefalse','Вводный инструктаж по ОТ можно провести в течение первой недели работы.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','Вводный инструктаж по ОТ проводится ДО начала работы — в первый день, до допуска к рабочему месту.'),
(lid,6,'choice','На какой день HR проводит первое exit-интервью с новичком?','[{"text":"14-й","is_correct":false},{"text":"30-й","is_correct":true},{"text":"60-й","is_correct":false},{"text":"90-й","is_correct":false}]','HR проводит exit-интервью на 30-й и 90-й день адаптации.'),
(lid,7,'scenario','Наставник игнорирует новичка. Что делать HR?','[{"text":"Уволить наставника","is_correct":false},{"text":"Напомнить о доплате, проверить снижение нагрузки, при отказе — заменить","is_correct":true},{"text":"Сказать новичку разбираться самому","is_correct":false},{"text":"Подождать — привыкнут друг к другу","is_correct":false}]','Напомнить о доплате и снижении нагрузки. Если принципиально отказывается — заменить. Не все подходят для роли наставника.');
END $$;

-- ═══════════════════════════════════════════════════════════════
-- УРОКИ 4-12 HR (краткие, но с полным контентом)
-- ═══════════════════════════════════════════════════════════════

-- УРОК 4: Трудовое право
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date)
VALUES (5, 'hr', 'Трудовое право — увольнения, отпуска, больничные', 'Кадровое дело', '💼', '#1e3828', $blocks$[
  {"type":"cover","icon":"💼","title":"Трудовое право","subtitle":"Увольнения, отпуска, больничные — без ошибок"},
  {"type":"intro","text":"Трудовое право — минное поле для HR. Одна ошибка в процедуре увольнения может стоить компании сотни тысяч рублей. В этом свитке — практические алгоритмы для самых частых ситуаций: увольнение, отпуск, больничный, дисциплинарное взыскание."},
  {"type":"text_block","title":"Виды увольнений и их риски","text":"По собственному желанию (ст. 80 ТК) — самый безопасный вариант. Работник пишет заявление за 14 дней. Важно: работник может отозвать заявление в любой момент до истечения срока, если на его место не приглашён другой работник письменно. По соглашению сторон (ст. 78 ТК) — рекомендуемый способ при конфликтных ситуациях. Оформляется письменное соглашение с указанием даты увольнения и компенсации. После подписания отозвать нельзя. По инициативе работодателя (ст. 81 ТК) — самый рискованный. Основания: прогул, появление в нетрезвом виде, неоднократное неисполнение обязанностей, сокращение штата. Каждое основание требует строгого соблюдения процедуры."},
  {"type":"warning","level":"danger","text":"Нельзя увольнять: беременных (кроме ликвидации), женщин с детьми до 3 лет, одиноких матерей с детьми до 14 лет, работников на больничном или в отпуске. Нарушение — восстановление + компенсация + штраф."},
  {"type":"steps","title":"Алгоритм оформления ежегодного отпуска","items":["График отпусков утверждается за 2 недели до нового года (ст. 123 ТК)","Уведомить работника о начале отпуска за 2 недели под подпись","Издать приказ об отпуске (Т-6)","Выплатить отпускные за 3 календарных дня до начала отпуска","Внести данные в табель учёта рабочего времени","При переносе — письменное заявление работника + приказ"]},
  {"type":"stat","value":"3 дня","label":"до начала отпуска — крайний срок выплаты отпускных (ст. 136 ТК)","source":"Трудовой кодекс РФ"},
  {"type":"fact_card","icon":"⚖️","text":"За несвоевременную выплату отпускных работодатель обязан выплатить компенсацию: 1/150 ключевой ставки ЦБ за каждый день задержки (ст. 236 ТК). При ставке 16% и отпускных 60 000 ₽ — это 64 ₽/день. Мелочь, но при проверке ГИТ — штраф до 50 000 ₽."},
  {"type":"highlight","text":"Увольнение по соглашению сторон — самый безопасный способ расставания при конфликте. После подписания работник не может отозвать согласие."},
  {"type":"quote","text":"Незнание закона не освобождает от ответственности","author":"Римское право"},
  {"type":"divider"}
]$blocks$::jsonb, 9, ARRAY['ТК РФ','увольнение','отпуск','больничный','право'], true, 'published', 'manual', NOW(), CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','За сколько дней до отпуска нужно выплатить отпускные?','[{"text":"1 день","is_correct":false},{"text":"3 дня","is_correct":true},{"text":"5 дней","is_correct":false},{"text":"7 дней","is_correct":false}]','Отпускные выплачиваются за 3 календарных дня до начала отпуска (ст. 136 ТК).'),
(lid,2,'truefalse','Работник может отозвать заявление об увольнении по собственному желанию в любой момент.','[{"text":"Верно","is_correct":true},{"text":"Неверно","is_correct":false}]','Да, работник может отозвать заявление в любой момент до истечения 14-дневного срока, если на его место не приглашён другой работник письменно.'),
(lid,3,'choice','Можно ли уволить беременную сотрудницу по инициативе работодателя?','[{"text":"Да, при наличии оснований","is_correct":false},{"text":"Нет, кроме ликвидации организации","is_correct":true},{"text":"Да, по соглашению сторон","is_correct":false},{"text":"Да, за прогул","is_correct":false}]','Беременных нельзя увольнять по инициативе работодателя, кроме случая ликвидации организации.'),
(lid,4,'choice','За сколько дней работник должен предупредить об увольнении по собственному?','[{"text":"3 дня","is_correct":false},{"text":"7 дней","is_correct":false},{"text":"14 дней","is_correct":true},{"text":"30 дней","is_correct":false}]','Работник предупреждает за 14 дней (ст. 80 ТК РФ).'),
(lid,5,'choice','Какой штраф за несвоевременную выплату отпускных?','[{"text":"10 000 ₽","is_correct":false},{"text":"30 000 ₽","is_correct":false},{"text":"50 000 ₽","is_correct":true},{"text":"100 000 ₽","is_correct":false}]','При проверке ГИТ штраф за несвоевременную выплату отпускных — до 50 000 ₽.');
END $$;

-- УРОКИ 5-8 (обязательные)
DO $$ DECLARE lid INT; BEGIN
INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date) VALUES
(6,'hr','HR-аналитика — текучесть, eNPS, стоимость найма','Кадровое дело','📊','#1e3830',$blocks$[{"type":"cover","icon":"📊","title":"HR-аналитика","subtitle":"Метрики, которые должен знать каждый HR"},{"type":"intro","text":"HR без аналитики — как врач без анализов. Вы не можете улучшить то, что не измеряете. В Асгарде действует система из 8 ключевых HR-метрик, которые отслеживаются ежемесячно в CRM."},{"type":"text_block","title":"8 ключевых HR-метрик Асгарда","text":"1) Текучесть персонала — процент уволившихся за период. Норма для строительной отрасли — до 25% в год. В Асгарде за 2025 — 19%. 2) Стоимость найма — все затраты на привлечение одного сотрудника: реклама, время HR, медосмотр. В Асгарде — 45 000 ₽ на рабочего, 120 000 ₽ на специалиста. 3) Время закрытия вакансии — от заявки до выхода. Норма: рабочие — 14 дней, специалисты — 30 дней. 4) eNPS — индекс лояльности сотрудников (от -100 до +100). Норма ≥+20. 5) Абсентеизм — процент пропущенных рабочих дней. Норма <5%. 6) Укомплектованность — процент заполненных позиций. Норма ≥95%. 7) Конверсия воронки — от отклика до выхода. 8) Текучесть новичков — увольнения в первые 90 дней."},{"type":"stat","value":"19%","label":"текучесть персонала Асгарда в 2025 году (норма отрасли — 25%)","source":"HR-отчёт"},{"type":"icon_grid","title":"Дашборд HR в CRM","items":[{"icon":"📉","label":"Текучесть 19%","desc":"Ниже отраслевой нормы 25% — хороший показатель"},{"icon":"💰","label":"Найм 45К ₽","desc":"Стоимость найма рабочего — 45 000 рублей"},{"icon":"⏱️","label":"14 дней","desc":"Среднее время закрытия вакансии рабочего"},{"icon":"😊","label":"eNPS +24","desc":"Индекс лояльности — выше нормы (+20)"},{"icon":"📊","label":"Укомпл. 97%","desc":"Укомплектованность штата — отличный показатель"},{"icon":"🔄","label":"Новички 18%","desc":"Текучесть новичков после программы адаптации"}]},{"type":"highlight","text":"eNPS (Employee Net Promoter Score) — главный индикатор здоровья компании. Вопрос один: «Порекомендуете ли вы Асгард как работодателя?» Шкала 0-10. Промоутеры (9-10) минус Критики (0-6) = eNPS."},{"type":"divider"}]$blocks$::jsonb,8,ARRAY['аналитика','текучесть','eNPS','метрики','KPI'],true,'published','manual',NOW(),CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Какова текучесть персонала Асгарда в 2025 году?','[{"text":"12%","is_correct":false},{"text":"19%","is_correct":true},{"text":"25%","is_correct":false},{"text":"32%","is_correct":false}]','Текучесть Асгарда — 19%, при отраслевой норме 25%.'),
(lid,2,'choice','Какова стоимость найма одного рабочего?','[{"text":"20 000 ₽","is_correct":false},{"text":"45 000 ₽","is_correct":true},{"text":"80 000 ₽","is_correct":false},{"text":"120 000 ₽","is_correct":false}]','Стоимость найма рабочего — 45 000 ₽, специалиста — 120 000 ₽.'),
(lid,3,'choice','Какова норма eNPS?','[{"text":"≥0","is_correct":false},{"text":"≥+10","is_correct":false},{"text":"≥+20","is_correct":true},{"text":"≥+50","is_correct":false}]','Норма eNPS — ≥+20. В Асгарде — +24.'),
(lid,4,'choice','За сколько дней нужно закрыть вакансию рабочего?','[{"text":"7 дней","is_correct":false},{"text":"14 дней","is_correct":true},{"text":"21 день","is_correct":false},{"text":"30 дней","is_correct":false}]','Норма закрытия вакансии рабочего — 14 дней.');
END $$;

-- УРОКИ 6-8 (обязательные, компактные)
DO $$ DECLARE lid INT; BEGIN INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date) VALUES
(7,'hr','Корпоративная культура — ценности, мероприятия, вовлечённость','Кадровое дело','🤝','#1e3020',$blocks$[{"type":"cover","icon":"🤝","title":"Корпоративная культура","subtitle":"Ценности Асгарда и как их транслировать"},{"type":"intro","text":"Культура ест стратегию на завтрак — эта фраза Питера Друкера особенно актуальна для Асгарда. Наши люди работают в экстремальных условиях, и именно культура — то, что удерживает команду вместе."},{"type":"text_block","title":"5 ценностей Асгарда","text":"1) Безопасность превыше всего — ни один проект не стоит здоровья человека. 2) Слово = дело — обещал заказчику сроки — выполни. 3) Команда — один за всех — на вахте нет «моё» и «твоё», есть общий результат. 4) Профессионализм — учись каждый день, расти в мастерстве. 5) Честность — с заказчиком, с коллегами, с собой. Эти ценности не просто слова на стене — они проверяются каждый день на объектах."},{"type":"stat","value":"5","label":"ценностей Асгарда — безопасность, слово, команда, профессионализм, честность","source":"Кодекс Асгарда"},{"type":"highlight","text":"Культура проявляется не в том, что написано на стене, а в том, как люди ведут себя, когда никто не смотрит."},{"type":"quote","text":"Культура ест стратегию на завтрак","author":"Питер Друкер"},{"type":"divider"}]$blocks$::jsonb,7,ARRAY['культура','ценности','вовлечённость'],true,'published','manual',NOW(),CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Сколько ценностей в кодексе Асгарда?','[{"text":"3","is_correct":false},{"text":"5","is_correct":true},{"text":"7","is_correct":false},{"text":"10","is_correct":false}]','5 ценностей: безопасность, слово=дело, команда, профессионализм, честность.'),
(lid,2,'choice','Какая ценность стоит на первом месте?','[{"text":"Профессионализм","is_correct":false},{"text":"Команда","is_correct":false},{"text":"Безопасность","is_correct":true},{"text":"Честность","is_correct":false}]','Безопасность превыше всего — ни один проект не стоит здоровья человека.');
END $$;

DO $$ DECLARE lid INT; BEGIN INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date) VALUES
(8,'hr','Охрана труда для HR — медосмотры, инструктажи, допуски','Кадровое дело','⚖️','#1e2830',$blocks$[{"type":"cover","icon":"⚖️","title":"Охрана труда для HR","subtitle":"Медосмотры, инструктажи и допуски — зона ответственности HR"},{"type":"intro","text":"Охрана труда — не только задача инженера по ОТ. HR отвечает за то, чтобы каждый сотрудник имел действующий медосмотр, прошёл все инструктажи и имел необходимые допуски ДО выхода на работу. Пропуск любого из этих шагов — штраф и уголовная ответственность при НС."},{"type":"text_block","title":"Виды обязательных медосмотров","text":"Предварительный — при приёме на работу. Периодический — раз в 1-2 года в зависимости от вредных факторов. Внеочередной — по направлению работодателя при подозрении на ухудшение здоровья. Для работников Асгарда обязательны: терапевт, хирург, невролог, офтальмолог, ЛОР, психиатр, нарколог. Стоимость медосмотра — 3 500-5 000 ₽, оплачивает работодатель. Срок действия — 1-2 года."},{"type":"warning","level":"danger","text":"Допуск к работе без медосмотра: штраф 110 000-130 000 ₽ за каждого работника (ст. 5.27.1 КоАП). При несчастном случае — уголовная ответственность по ст. 143 УК РФ (до 5 лет лишения свободы)."},{"type":"stat","value":"130 000 ₽","label":"штраф за допуск к работе без медосмотра — за каждого работника","source":"КоАП РФ"},{"type":"steps","title":"Чек-лист допусков для вахтового рабочего","items":["Медосмотр — действующий, не просрочен","Вводный инструктаж по ОТ — в первый день","Инструктаж на рабочем месте — до начала работ","Обучение по ОТ (40 часов) — в течение месяца","Допуск к работам на высоте (при необходимости)","Аттестация НАКС (для сварщиков)","Удостоверение стропальщика (при необходимости)","Пожарно-технический минимум"]},{"type":"highlight","text":"HR ведёт реестр допусков в CRM. За 30 дней до истечения — автоматическое уведомление. Просроченный допуск = запрет на выезд."},{"type":"divider"}]$blocks$::jsonb,8,ARRAY['ОТ','медосмотр','инструктаж','допуски','безопасность'],true,'published','manual',NOW(),CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Каков штраф за допуск к работе без медосмотра?','[{"text":"50 000 ₽","is_correct":false},{"text":"80 000 ₽","is_correct":false},{"text":"110 000-130 000 ₽","is_correct":true},{"text":"200 000 ₽","is_correct":false}]','Штраф 110 000-130 000 ₽ за каждого работника (ст. 5.27.1 КоАП).'),
(lid,2,'choice','Кто оплачивает медосмотр?','[{"text":"Работник","is_correct":false},{"text":"Работодатель","is_correct":true},{"text":"50/50","is_correct":false},{"text":"Страховая","is_correct":false}]','Медосмотр оплачивает работодатель. Стоимость — 3 500-5 000 ₽.'),
(lid,3,'truefalse','Вводный инструктаж можно провести в течение первой недели работы.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','Вводный инструктаж проводится в первый день, ДО начала работы.'),
(lid,4,'choice','За сколько дней до истечения допуска CRM отправляет уведомление?','[{"text":"7 дней","is_correct":false},{"text":"14 дней","is_correct":false},{"text":"30 дней","is_correct":true},{"text":"60 дней","is_correct":false}]','За 30 дней до истечения — автоматическое уведомление в CRM.');
END $$;

DO $$ DECLARE lid INT; BEGIN INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date) VALUES
(9,'hr','Компенсации и льготы — ЗП, суточные, премии, ДМС','Кадровое дело','💰','#1e3828',$blocks$[{"type":"cover","icon":"💰","title":"Компенсации и льготы","subtitle":"Зарплата, суточные, премии и социальный пакет"},{"type":"intro","text":"Система компенсаций — главный инструмент привлечения и удержания персонала. В Асгарде она состоит из 4 компонентов: базовая зарплата, суточные на вахте, премии за результат и социальный пакет."},{"type":"text_block","title":"Структура компенсации вахтового рабочего","text":"Базовая зарплата — фиксированная ставка за смену (день/ночь). Зависит от разряда, квалификации и региона. Суточные — ежедневная выплата на вахте: питание, бытовые расходы. В Асгарде — 1 500-2 500 ₽/день в зависимости от региона. Вахтовая надбавка — 75% тарифной ставки за каждый день вахты в районах Крайнего Севера (ст. 302 ТК). Премия — по итогам проекта: досрочное завершение, отсутствие замечаний по качеству, ноль инцидентов ТБ. Размер — до 30% от заработка за проект."},{"type":"stat","value":"1 500-2 500 ₽","label":"суточные на вахте в зависимости от региона","source":"Положение об оплате труда"},{"type":"warning","level":"warning","text":"Суточные выплачиваются строго вовремя — задержка даже на 2-3 дня разрушает доверие бригады. HR контролирует своевременность выплат через CRM."},{"type":"highlight","text":"Премия до 30% за проект: досрочное завершение + качество + ноль инцидентов ТБ. Это мотивирует бригаду работать быстро, качественно и безопасно."},{"type":"divider"}]$blocks$::jsonb,7,ARRAY['зарплата','суточные','премии','компенсации','ДМС'],true,'published','manual',NOW(),CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Каков размер суточных на вахте в Асгарде?','[{"text":"500-1 000 ₽","is_correct":false},{"text":"1 500-2 500 ₽","is_correct":true},{"text":"3 000-5 000 ₽","is_correct":false},{"text":"Не выплачиваются","is_correct":false}]','Суточные — 1 500-2 500 ₽/день в зависимости от региона.'),
(lid,2,'choice','Какой максимальный размер премии за проект?','[{"text":"10%","is_correct":false},{"text":"20%","is_correct":false},{"text":"30%","is_correct":true},{"text":"50%","is_correct":false}]','Премия — до 30% от заработка за проект.'),
(lid,3,'choice','Какова вахтовая надбавка в районах Крайнего Севера?','[{"text":"50% тарифной ставки","is_correct":false},{"text":"75% тарифной ставки","is_correct":true},{"text":"100% тарифной ставки","is_correct":false},{"text":"Не предусмотрена","is_correct":false}]','75% тарифной ставки за каждый день вахты в районах Крайнего Севера (ст. 302 ТК).');
END $$;

-- УРОКИ 9-12 (необязательные)
DO $$ DECLARE lid INT; BEGIN INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date) VALUES
(10,'hr','CRM Асгарда для HR — заявки, анкеты, документы','Кадровое дело','📱','#1e3828',$blocks$[{"type":"cover","icon":"📱","title":"CRM для HR","subtitle":"Как использовать систему для кадровой работы"},{"type":"intro","text":"CRM Асгарда автоматизирует 70% рутинной HR-работы: заявки на подбор, анкеты кандидатов, реестр допусков, табель, расчёт зарплаты. HR, который не использует CRM — тратит в 3 раза больше времени на ту же работу."},{"type":"text_block","title":"Модули CRM для HR","text":"Модуль «Персонал» — полная база сотрудников: анкеты, допуски, медосмотры, история работы. Модуль «Заявки HR» — заявки на подбор от руководителей с автоматическим трекингом статуса. Модуль «Допуски» — реестр всех допусков с автоуведомлениями за 30 дней до истечения. Модуль «Табель» — учёт рабочего времени с автоматическим расчётом переработок. Модуль «Зарплата» — расчёт ЗП, суточных, премий с выгрузкой в 1С."},{"type":"stat","value":"70%","label":"рутинной HR-работы автоматизировано в CRM","source":"Аналитика использования"},{"type":"highlight","text":"Реестр допусков в CRM — автоуведомление за 30 дней до истечения. Просроченный допуск = запрет на выезд."},{"type":"divider"}]$blocks$::jsonb,7,ARRAY['CRM','автоматизация','допуски','табель'],false,'published','manual',NOW(),CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Какой процент HR-работы автоматизирован в CRM?','[{"text":"30%","is_correct":false},{"text":"50%","is_correct":false},{"text":"70%","is_correct":true},{"text":"90%","is_correct":false}]','CRM автоматизирует 70% рутинной HR-работы.');
END $$;

DO $$ DECLARE lid INT; BEGIN INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date) VALUES
(11,'hr','Оценка компетенций — грейды, аттестация, развитие','Кадровое дело','🧠','#1e3020',$blocks$[{"type":"cover","icon":"🧠","title":"Оценка компетенций","subtitle":"Грейды, аттестация и план развития сотрудников"},{"type":"intro","text":"Оценка компетенций — инструмент развития, а не наказания. В Асгарде действует система грейдов для рабочих (4 уровня) и специалистов (3 уровня). Каждый грейд — это набор навыков, ответственности и зарплатная вилка."},{"type":"text_block","title":"Система грейдов для рабочих","text":"Грейд 1 (Новичок): базовые навыки, работа под наблюдением, ставка 2 000-2 500 ₽/смена. Грейд 2 (Специалист): самостоятельная работа, 1-2 допуска, ставка 2 500-3 500 ₽/смена. Грейд 3 (Мастер): может обучать других, 3+ допуска, ставка 3 500-5 000 ₽/смена. Грейд 4 (Эксперт): наставник, может руководить бригадой, все допуски, ставка 5 000-7 000 ₽/смена. Переход между грейдами — по результатам аттестации раз в 6 месяцев."},{"type":"stat","value":"4","label":"грейда для рабочих — от Новичка до Эксперта","source":"Система грейдов Асгарда"},{"type":"highlight","text":"Аттестация — раз в 6 месяцев. Критерии: навыки, допуски, отзывы мастеров, результаты в Академии Мимира."},{"type":"divider"}]$blocks$::jsonb,7,ARRAY['грейды','аттестация','компетенции','развитие'],false,'published','manual',NOW(),CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Сколько грейдов для рабочих в системе Асгарда?','[{"text":"3","is_correct":false},{"text":"4","is_correct":true},{"text":"5","is_correct":false},{"text":"6","is_correct":false}]','4 грейда: Новичок, Специалист, Мастер, Эксперт.'),
(lid,2,'choice','Как часто проводится аттестация?','[{"text":"Раз в 3 месяца","is_correct":false},{"text":"Раз в 6 месяцев","is_correct":true},{"text":"Раз в год","is_correct":false},{"text":"Раз в 2 года","is_correct":false}]','Аттестация проводится раз в 6 месяцев.');
END $$;

DO $$ DECLARE lid INT; BEGIN INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date) VALUES
(12,'hr','Кадровый аудит — проверки ГИТ, штрафы, подготовка','Кадровое дело','📝','#1e3828',$blocks$[{"type":"cover","icon":"📝","title":"Кадровый аудит","subtitle":"Как подготовиться к проверке ГИТ и не получить штраф"},{"type":"intro","text":"Проверка ГИТ (Государственной инспекции труда) — стресс для любого HR. Но если кадровый учёт ведётся правильно, проверка проходит без штрафов. В этом свитке — чек-лист подготовки и типичные нарушения."},{"type":"text_block","title":"Топ-5 нарушений при проверках ГИТ","text":"1) Отсутствие или неправильное оформление трудовых договоров — штраф до 100 000 ₽ за каждого. 2) Нарушение порядка ведения трудовых книжек — штраф до 50 000 ₽. 3) Отсутствие обязательных инструктажей по ОТ — штраф до 130 000 ₽. 4) Нарушение порядка предоставления отпусков — штраф до 50 000 ₽. 5) Подмена трудовых отношений ГПХ — штраф до 100 000 ₽. Общая сумма штрафов при серьёзных нарушениях может достигать 1-2 млн рублей."},{"type":"stat","value":"1-2 млн ₽","label":"возможная сумма штрафов при серьёзных нарушениях кадрового учёта","source":"Практика проверок ГИТ"},{"type":"warning","level":"danger","text":"При повторном нарушении штрафы удваиваются, а должностное лицо может быть дисквалифицировано на срок до 3 лет."},{"type":"checklist","title":"Чек-лист подготовки к проверке ГИТ","items":["Все трудовые договоры подписаны и хранятся","Приказы о приёме/увольнении/переводе оформлены","Трудовые книжки заполнены корректно","Журналы инструктажей ведутся","Медосмотры актуальны","График отпусков утверждён","Табель учёта рабочего времени ведётся","Расчётные листки выдаются"]},{"type":"divider"}]$blocks$::jsonb,8,ARRAY['аудит','ГИТ','штрафы','проверка','документы'],false,'published','manual',NOW(),CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Какова максимальная сумма штрафов при серьёзных нарушениях?','[{"text":"100 000 ₽","is_correct":false},{"text":"500 000 ₽","is_correct":false},{"text":"1-2 млн ₽","is_correct":true},{"text":"5 млн ₽","is_correct":false}]','Общая сумма штрафов может достигать 1-2 млн рублей.'),
(lid,2,'truefalse','При повторном нарушении штрафы остаются прежними.','[{"text":"Верно","is_correct":false},{"text":"Неверно","is_correct":true}]','При повторном нарушении штрафы удваиваются + возможна дисквалификация до 3 лет.');
END $$;

DO $$ DECLARE lid INT; BEGIN INSERT INTO office_academy_lessons (month_number, track, title, saga, cover_icon, cover_color, blocks, estimated_minutes, tags, is_mandatory, status, generated_by, published_at, release_date) VALUES
(13,'hr','HR-бренд — привлечение, удержание, репутация работодателя','Кадровое дело','🎯','#1e3020',$blocks$[{"type":"cover","icon":"🎯","title":"HR-бренд","subtitle":"Как стать работодателем мечты в строительной отрасли"},{"type":"intro","text":"HR-бренд — это то, что говорят о вас кандидаты и сотрудники. В строительной отрасли, где дефицит квалифицированных рабочих, сильный HR-бренд — конкурентное преимущество. Асгард инвестирует в репутацию работодателя через 4 канала."},{"type":"text_block","title":"4 канала HR-бренда Асгарда","text":"1) Отзывы сотрудников — мониторинг на HH.ru, Glassdoor, Dream Job. Цель — рейтинг ≥4.2 из 5. 2) Социальные сети — истории сотрудников, фото с объектов, достижения команды. 3) Программа «Приведи друга» — лучшая реклама — рекомендация от своего. 4) Участие в отраслевых мероприятиях — конференции, выставки, дни открытых дверей. Результат: 40% кандидатов приходят «по имени» — знают Асгард и хотят работать именно у нас."},{"type":"stat","value":"40%","label":"кандидатов приходят «по имени» — знают Асгард как работодателя","source":"HR-аналитика 2025"},{"type":"highlight","text":"Рейтинг работодателя на HH.ru ≥4.2 — цель HR-бренда. Каждый негативный отзыв требует публичного ответа в течение 24 часов."},{"type":"divider"}]$blocks$::jsonb,6,ARRAY['HR-бренд','репутация','привлечение','удержание'],false,'published','manual',NOW(),CURRENT_DATE) RETURNING id INTO lid;
INSERT INTO office_academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation) VALUES
(lid,1,'choice','Какой процент кандидатов приходит «по имени»?','[{"text":"15%","is_correct":false},{"text":"25%","is_correct":false},{"text":"40%","is_correct":true},{"text":"60%","is_correct":false}]','40% кандидатов приходят, зная Асгард как работодателя.'),
(lid,2,'choice','Какой целевой рейтинг работодателя на HH.ru?','[{"text":"3.5","is_correct":false},{"text":"4.0","is_correct":false},{"text":"4.2","is_correct":true},{"text":"4.8","is_correct":false}]','Цель — рейтинг ≥4.2 из 5 на HH.ru.');
END $$;
